def subgrid_sums(grid):
  R, C = len(grid), len(grid[0])
  res = [row.copy() for row in grid]
  for r in range(R - 1, -1, -1):
    for c in range(C - 1, -1, -1):
      if r + 1 < R:
        res[r][c] += res[r + 1][c]
      if c + 1 < C:
        res[r][c] += res[r][c + 1]
      if r + 1 < R and c + 1 < C:  # subtract doublecounted subgrid
        res[r][c] -= res[r + 1][c + 1]
  return res

