function subgridSums(grid) {
  const R = grid.length;
  const C = grid[0].length;
  const res = grid.map((row) => [...row]);
  for (let r = R - 1; r >= 0; r--) {
    for (let c = C - 1; c >= 0; c--) {
      if (r + 1 < R) {
        res[r][c] += res[r + 1][c];
      }
      if (c + 1 < C) {
        res[r][c] += res[r][c + 1];
      }
      if (r + 1 < R && c + 1 < C) {
        // subtract doublecounted subgrid
        res[r][c] -= res[r + 1][c + 1];
      }
    }
  }
  return res;
}

