class SubgridSums {
  public int[][] solve(int[][] grid) {
    final int R = grid.length;
    final int C = grid[0].length;
    int[][] res = new int[R][C];
    for (int r = 0; r < R; r++) {
      res[r] = Arrays.copyOf(grid[r], C);
    }

    for (int r = R - 1; r >= 0; r--) {
      for (int c = C - 1; c >= 0; c--) {
        if (r + 1 < R) {
          res[r][c] += res[r + 1][c];
        }
        if (c + 1 < C) {
          res[r][c] += res[r][c + 1];
        }
        if (r + 1 < R && c + 1 < C) { // subtract doublecounted subgrid
          res[r][c] -= res[r + 1][c + 1];
        }
      }
    }
    return res;
  }
}

