class RunTests {
  public void runTests() {
    Object[][] tests = {
        // Example from book
        { new int[][] {
            { -1, 2, 3 },
            { 4, 0, 0 },
            { -2, 0, 9 }
        }, new int[][] {
            { 15, 14, 12 },
            { 11, 9, 9 },
            { 7, 9, 9 }
        } },
        // Edge case - 1x1 grid
        { new int[][] { { 5 } }, new int[][] { { 5 } } },
        // Edge case - single row
        { new int[][] { { 1, 2, 3 } }, new int[][] { { 6, 5, 3 } } },
        // Edge case - single column
        { new int[][] { { 1 }, { 2 }, { 3 } },
            new int[][] { { 6 }, { 5 }, { 3 } } },
        // Edge case - all zeros
        { new int[][] {
            { 0, 0 },
            { 0, 0 }
        }, new int[][] {
            { 0, 0 },
            { 0, 0 }
        } },
    };

    SubgridSums solution = new SubgridSums();
    for (Object[] test : tests) {
      int[][] grid = (int[][]) test[0];
      int[][] want = (int[][]) test[1];
      int[][] got = solution.solve(grid);
      if (!Arrays.deepEquals(got, want)) {
        throw new RuntimeException(String.format(
            "\nsolve(%s): got: %s, want: %s\n",
            Arrays.deepToString(grid), Arrays.deepToString(got),
            Arrays.deepToString(want)));
      }
    }
  }
}

public class Solution {
  public static void main(String[] args) {
    new RunTests().runTests();
  }
}
